const (
	// The "cache-dir" property indicates the backend's local directory for
	// cached data.
	CLIENT_BACKEND_PROPERTY_CACHE_DIR string = "cache-dir"
	// The "capabilities" property is a comma-separated list of capabilities
	// supported by the backend.  The preferred method of retrieving and working
	// with capabilities is e_client_get_capabilities() and
	// e_client_check_capability().
	CLIENT_BACKEND_PROPERTY_CAPABILITIES string = "capabilities"
	// The "online" property is "TRUE" when the client is fully opened and
	// online, "FALSE" at all other times.  See also e_client_is_online().
	CLIENT_BACKEND_PROPERTY_ONLINE string = "online"
	// The "opened" property is "TRUE" when the client is fully opened,
	// "FALSE" at all other times.
	CLIENT_BACKEND_PROPERTY_OPENED string = "opened"
	// The "opening" property is "TRUE" when the client is in the process of
	// opening, "FALSE" at all other times.
	CLIENT_BACKEND_PROPERTY_OPENING string = "opening"
	// The "online" property is "TRUE" if the backend has only read access
	// to its data, "FALSE" if the backend can modify its data.  See also
	// e_client_is_readonly().
	CLIENT_BACKEND_PROPERTY_READONLY string = "readonly"
	// The current overall revision string, this can be used as
	// a quick check to see if data has changed at all since the
	// last time the revision was observed.
	CLIENT_BACKEND_PROPERTY_REVISION string = "revision"
)

// Error codes for #EClient operations.
type ClientError int

const (

	// Invalid argument was used
	EClientErrorInvalidArgValue ClientError = 0
	// The client is busy
	EClientErrorBusyValue ClientError = 1
	// The source is not loaded
	EClientErrorSourceNotLoadedValue ClientError = 2
	// The source is already loaded
	EClientErrorSourceAlreadyLoadedValue ClientError = 3
	// Authentication failed
	EClientErrorAuthenticationFailedValue ClientError = 4
	// Authentication required
	EClientErrorAuthenticationRequiredValue ClientError = 5
	// The repository (client) is offline
	EClientErrorRepositoryOfflineValue ClientError = 6
	// The operation is unavailable in offline mode
	EClientErrorOfflineUnavailableValue ClientError = 7
	// Permission denied for the operation
	EClientErrorPermissionDeniedValue ClientError = 8
	// The operation was cancelled
	EClientErrorCancelledValue ClientError = 9
	// The operation cannot be cancelled
	EClientErrorCouldNotCancelValue ClientError = 10
	// The operation is not supported
	EClientErrorNotSupportedValue ClientError = 11
	// TLS is not available
	EClientErrorTlsNotAvailableValue ClientError = 12
	// Requested authentication method is not supported
	EClientErrorUnsupportedAuthenticationMethodValue ClientError = 13
	// Search size limit exceeded
	EClientErrorSearchSizeLimitExceededValue ClientError = 14
	// Search time limit exceeded
	EClientErrorSearchTimeLimitExceededValue ClientError = 15
	// The query was invalid
	EClientErrorInvalidQueryValue ClientError = 16
	// The query was refused by the server side
	EClientErrorQueryRefusedValue ClientError = 17
	// A D-Bus error occurred
	EClientErrorDbusErrorValue ClientError = 18
	// Other error
	EClientErrorOtherErrorValue ClientError = 19
	// The client is not opened
	EClientErrorNotOpenedValue ClientError = 20
	// The client is out of sync with the server
	EClientErrorOutOfSyncValue ClientError = 21
)

