func (x *Client) ConnectBackendDied(cb *func(Client)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "backend-died", cbRefPtr)
	}

	fcb := func(clsPtr uintptr) {
		fa := Client{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "backend-died", cbRefPtr)
}

func (x *Client) ConnectBackendError(cb *func(Client, string)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "backend-error", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, ObjectVarp string) {
		fa := Client{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, ObjectVarp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "backend-error", cbRefPtr)
}

